"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 main phase: one row per decision window, with the gold labels and every input a system may use.

Sets: "train" (data/p1v4/render/train_d00..d11: draws 0-11 of the single-line parts, renders 0-3 of the episodes),
"dev". Test and replication load only with final=True (plan 8.5: run once, at the end, after the freeze). Units in
results/step0_v04/excluded_units.json are left out everywhere (plan 8.4).

Window fields: id ("unit|version|k"), unit, version, k, part, subset, split, path (8 s wav ending at the decision
point), t (decision time, seconds from the unit start), kind (R, S or RS: what is asked), gold ({"S", "R"}; None
where not scored), line (id of the line just said, or None), category, assistant_speaking, events (detector targets
inside the window: [(class, start, end)] in window seconds), key (unit, version) of the meta row in ROWS.
"""
import glob
import json
import os

import numpy as np

DET_CLASSES = ["phone", "doorbell", "knock", "footsteps", "door", "cabinet", "decoy"]
WIN_S = 8.0
SR = 16000
RENDER = "data/p1v4/render"


def excluded():
    path = "results/step0_v04/excluded_units.json"
    return {u for us in json.load(open(path, encoding="utf-8"))["units"].values() for u in us}


FREEZE = "results/main_v04/freeze.json"     # written at the freeze (plan 8.1 step 4); absent before it


def final_unlocked():
    """True only in the single final run: the freeze record exists AND the run sets P1V4_FINAL_RUN=1 (added 2026-11-16
    so the final runner can reuse every component's loader; before the freeze nothing can open test or replication)."""
    return os.environ.get("P1V4_FINAL_RUN") == "1" and os.path.exists(FREEZE)


# Step-0 seals (results/step0_v04/render_*_log.txt; docs/iterations.md, 2026-11-15): sha256 of the sorted window hashes
# recorded in each split's meta rows. Checked when a sealed split is opened (added 2026-11-21, pre-test code review).
SEALS = {"dev": "bed5840624838f637ed4c971de237d4805f93970046a2949d07ba24322fe2f94",
         "test": "5b87be44ca7b580e2ec8383e97f80f00ba3ca6d482b96731741c184a74ca54b7",
         "replication": "bef10c3c96d1f066adc0e07fa51ec1b27334943b824335a1a5c44704691e6bcf"}
_SEAL_OK = set()


def seal_of(which):
    """The seal recomputed from the split's meta rows, as scripts/p1v4_render_split.py printed it."""
    import hashlib
    rows = [json.loads(line) for line in open(os.path.join(RENDER, which, "meta.jsonl"), encoding="utf-8")]
    return hashlib.sha256("".join(sorted(p["sha256"] for r in rows for p in r["points"])).encode()).hexdigest()


def verify_seal(which, files=False):
    """Stop unless the split's meta rows still give its step-0 seal; files=True also re-hashes every window file
    against its recorded sha256 (a few minutes on test; run once on test day: `p1v4_data.py verify-seal test`)."""
    if which in _SEAL_OK and not files:
        return
    got = seal_of(which)
    if got != SEALS[which]:
        raise RuntimeError(f"{which}: seal {got} differs from the step-0 seal {SEALS[which]}: stop (plan 8.5)")
    if files:
        import hashlib
        bad = []
        for line in open(os.path.join(RENDER, which, "meta.jsonl"), encoding="utf-8"):
            for p in json.loads(line)["points"]:
                if hashlib.sha256(open(p["window"], "rb").read()).hexdigest() != p["sha256"]:
                    bad.append(p["window"])
        if bad:
            raise RuntimeError(f"{which}: {len(bad)} window files differ from their recorded hashes, first {bad[:3]}")
    _SEAL_OK.add(which)


_FREEZE_OK = []


def verify_freeze_once():
    """When a sealed split opens: the freeze record must match its files (p1v4_freeze.verify_or_stop), once per
    process (added 2026-11-21: covers every front-end and final command without touching each script)."""
    if not _FREEZE_OK:
        import p1v4_freeze as FZ            # imported here: p1v4_freeze imports this module
        FZ.verify_or_stop()
        _FREEZE_OK.append(True)


def sealed_name(name):
    """A render folder of test or replication, or a variant folder made from them (test_dnoise10, ...)."""
    base = os.path.basename(str(name).rstrip("/\\"))
    return base.split("_d")[0] in ("test", "replication")


def check_folder_name(name):
    """For code that names render folders directly (e.g. Context(None, folders=[...])): the same lock as folders()."""
    if sealed_name(name):
        if not final_unlocked():
            raise RuntimeError(f"{name} is sealed until the single final run (plan 8.5)")
        verify_freeze_once()
        base = os.path.basename(str(name).rstrip("/\\"))
        if base in SEALS:
            verify_seal(base)


def folders(which, final=False):
    """Render folders of a set. Test and replication open only when final_unlocked() holds; the `final` argument no
    longer opens them (changed 2026-11-20, freeze-amendment review: the grounding package passed final=True for any
    split other than dev, so a stray command could read test before the freeze). It is kept for old callers.
    Added 2026-11-21: when they open, the freeze record is verified (once per process) and their step-0 seal is
    checked (verify_seal)."""
    if which in ("test", "replication"):
        if not final_unlocked():
            raise RuntimeError(f"{which} is sealed until the single final run (plan 8.5)")
        verify_freeze_once()
        verify_seal(which)
    if which == "train":
        return sorted(glob.glob(f"{RENDER}/train_d??"))
    if which in ("dev", "test", "replication"):
        return [f"{RENDER}/{which}"]
    raise ValueError(which)


def folder_rows(d, ex=None):
    """Meta rows of one render folder, excluded units left out."""
    ex = excluded() if ex is None else ex
    rows = []
    for line in open(os.path.join(d, "meta.jsonl"), encoding="utf-8"):
        r = json.loads(line)
        if "error" in r:
            raise RuntimeError(f"render error in {d}: {r.get('unit')}")
        if r["unit"] not in ex:
            rows.append(r)
    return rows


def load_rows(which, final=False):
    """Meta rows (one per unit version) of a set, excluded units left out."""
    ex = excluded()
    return [r for d in folders(which, final) for r in folder_rows(d, ex)]


def folder_names(which, final=False):
    return [os.path.basename(d) for d in folders(which, final)]


def window_events(r, t):
    """Detector targets inside the window [t - 8, t]: the clip sources of the detector's classes."""
    w0 = t - WIN_S
    out = []
    for s in r["sources"]:
        if s["kind"] == "clip" and s.get("cls") in DET_CLASSES and s["end"] > w0 and s["start"] < t:
            out.append((s["cls"], max(0.0, s["start"] - w0), min(WIN_S, s["end"] - w0)))
    return out


def windows_of(rows, split):
    out = []
    for r in rows:
        for p in r["points"]:
            out.append({"id": f"{r['unit']}|{r['version']}|{p['k']}", "unit": r["unit"], "version": r["version"],
                        "k": p["k"], "part": r["part"], "subset": r["subset"], "split": split,
                        "path": p["window"], "t": p["t"], "kind": p["kind"], "gold": p["gold"],
                        "line": p.get("line"), "category": p.get("category"),
                        "assistant_speaking": p.get("assistant_speaking"),
                        "events": window_events(r, p["t"]), "key": (r["unit"], r["version"])})
    return out


def load_windows(which, final=False):
    rows = load_rows(which, final)
    return windows_of(rows, which), {(r["unit"], r["version"]): r for r in rows}


def frame_targets(events, n_frames, fps=100):
    t = np.zeros((n_frames, len(DET_CLASSES)), np.float32)
    for cls, a, b in events:
        t[int(np.ceil(a * fps)):int(np.floor(b * fps)) + 1, DET_CLASSES.index(cls)] = 1.0
    return t


GPU_FRACTION = 0.85


def gpu_guard(fraction=GPU_FRACTION):
    """On Windows the driver lets CUDA allocations spill past the card into shared system memory, which slows a job
    20-fold or more without any error (L1 at micro-batch 4 on the longest texts: 16 GB on the 8 GB card, 26 s per
    step). Cap PyTorch's allocator below the card (about 1.1 GB of the 7.96 GB is the CUDA context and other
    processes) so that a job that does not fit fails with an out-of-memory error instead."""
    import torch
    if torch.cuda.is_available():
        torch.cuda.set_per_process_memory_fraction(fraction)


if __name__ == "__main__":
    import sys
    # verify-seal <split> [--files]: dev any time; test and replication only in the final run (the lock applies)
    if len(sys.argv) >= 3 and sys.argv[1] == "verify-seal":
        which = sys.argv[2]
        if which in ("test", "replication"):
            if not final_unlocked():
                raise SystemExit(f"{which} is sealed until the single final run (plan 8.5)")
            verify_freeze_once()
        verify_seal(which, files="--files" in sys.argv)
        print(f"{which}: seal {SEALS[which]} verified" + (" with every window file" if "--files" in sys.argv else ""))
    else:
        raise SystemExit("usage: python -X utf8 scripts/p1v4_data.py verify-seal dev|test|replication [--files]")
